using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Usage;[Authorize(Policy="PlatformAuditRead")]public sealed class IndexModel(OrcaFacilDbContext db):PageModel{public IReadOnlyList<Row>Items{get;private set;}=[];public async Task OnGetAsync(CancellationToken ct)=>Items=await(from e in db.AccountModuleUsageEvents.AsNoTracking()join a in db.BusinessAccounts.AsNoTracking()on e.AccountId equals a.Id where !e.IsDeleted&&!a.IsDeleted group e by new{a.DisplayName,e.ModuleCode} into g orderby g.Count() descending select new Row(g.Key.DisplayName,g.Key.ModuleCode,g.Count(),g.Select(x=>x.UserId).Distinct().Count(),g.Max(x=>x.OccurredAt))).Take(100).ToListAsync(ct);public sealed record Row(string Account,string Module,int Events,int Users,DateTime Last);}
